{
  "segment_function": "Examine the distinction between the division of labor and the specialization of work, contrasting laboring processes with work processes and mass production.",
  "claims": [
    {
      "claim": "Division of labor grows directly out of the laboring process and is distinct from the specialization of work.",
      "claim_type": "author_position",
      "supporting_excerpt": "Division of labor indeed grows directly out of the laboring process and should not be mistaken for the apparently similar principle of specialization which prevails in working processes and with which it is usually equated.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "Division of labor presupposes the qualitative equivalence of all single activities requiring no special skill, whereas specialization of work is guided by the finished product requiring different skills.",
      "claim_type": "author_position",
      "supporting_excerpt": "Yet, while specialization of work is essentially guided by the finished product itself, whose nature it is to require different skills which then are pooled and organized together, division of labor, on the contrary, presupposes the qualitative equivalence of all single activities for which no special skill is required",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "division of labor",
      "definition": "A principle growing out of the laboring process that presupposes the qualitative equivalence of all single activities requiring no special skill, representing additive amounts of labor power."
    },
    {
      "term": "specialization of work",
      "definition": "A principle prevailing in working processes that is guided by the finished product and requires different skills which are pooled and organized together."
    }
  ],
  "distinctions": [
    {
      "item_a": "division of labor",
      "item_b": "specialization of work",
      "distinction": "Division of labor presupposes qualitative equivalence of unskilled activities and relates to the laboring process, whereas specialization of work is guided by finished products requiring diverse skills pooled together in working processes."
    }
  ],
  "must_not_be_lost": [
    "Division of labor is rooted in the laboring process, while specialization belongs to working processes.",
    "Mass production relies fundamentally on the replacement of workmen and specialization with laborers and the division of labor."
  ]
}

